def check_diverse(S, n):
    # Color 0
    G0 = nx.Graph()
    for i, flag in enumerate(S):
        for j in range(n):
            if flag[j] == 0:
                G0.add_edge(i, j + len(S))
    matching0 = nx.bipartite.matching.hopcroft_karp_matching(G0, top_nodes=range(len(S)))
    if len(matching0) // 2 >= n:
        return True

    # Color 1
    G1 = nx.Graph()
    for i, flag in enumerate(S):
        for j in range(n):
            if flag[j] == 1:
                G1.add_edge(i, j + len(S))
    matching1 = nx.bipartite.matching.hopcroft_karp_matching(G1, top_nodes=range(len(S)))
    if len(matching1) // 2 >= n:
        return True

    return False

